    public static string T(string key, string fallback = "")
    {
        string lang = Settings.Language;
        if (Strings.TryGetValue(key, out var dict))
        {
            if (dict.TryGetValue(lang, out var val) && !string.IsNullOrEmpty(val))
                return val;
            if (dict.TryGetValue("ru", out var ruVal) && !string.IsNullOrEmpty(ruVal))
                return ruVal;
            if (dict.TryGetValue("en", out var enVal) && !string.IsNullOrEmpty(enVal))
                return enVal;
        }
        return string.IsNullOrEmpty(fallback) ? key : fallback;
    }
}
